package com.yeyamo_mobile.api.graph_service.application;
import org.springframework.data.neo4j.core.Neo4jClient;import org.springframework.stereotype.Service;import java.util.*;
@Service public class CultureGraphQueryService{private final Neo4jClient neo;public CultureGraphQueryService(Neo4jClient n){neo=n;}public record Relation(String sourceType,String sourceId,String relation,String targetType,String targetId){}
 public List<Relation>related(String label,String id,int limit){if(!Set.of("Artwork","Culture","Language","Artisan").contains(label))throw new IllegalArgumentException("Unsupported graph label");return query("MATCH (a:"+label+" {id:$id})-[r]-(b) RETURN labels(a)[0] sourceType,a.id sourceId,type(r) relation,labels(b)[0] targetType,b.id targetId LIMIT $limit",id,limit);}
 public List<Relation>exploreCulture(String id,int limit){return query("MATCH (a {id:$id})-[r1]-(culture:Culture)-[r2]-(b) RETURN labels(culture)[0] sourceType,culture.id sourceId,type(r2) relation,labels(b)[0] targetType,b.id targetId LIMIT $limit",id,limit);}
 public List<Relation>discover(String country,String language,int limit){String q="MATCH (a)-[r]-(b) WHERE ($country = '' OR a.countryCode=$country OR a.id=$country) AND ($language = '' OR a.primaryLanguageCode=$language OR a.id=$language) RETURN labels(a)[0] sourceType,a.id sourceId,type(r) relation,labels(b)[0] targetType,b.id targetId LIMIT $limit";return fetch(q,Map.of("country",country==null?"":country,"language",language==null?"":language,"limit",cap(limit)));}
 private List<Relation>query(String q,String id,int limit){return fetch(q,Map.of("id",id,"limit",cap(limit)));}private int cap(int l){return Math.min(Math.max(l,1),100);}private List<Relation>fetch(String q,Map<String,Object>p){return neo.query(q).bindAll(p).fetchAs(Relation.class).mappedBy((t,r)->new Relation(r.get("sourceType").asString(),r.get("sourceId").asString(),r.get("relation").asString(),r.get("targetType").asString(),r.get("targetId").asString())).all().stream().toList();}}
